mapper.select:
/* buttle.apptpl.sup.inquiry.mapper.InquiryTypeMapper.selectInquiryTypeList */ SELECT cmmn_cd AS cd, cmmn_cd_nm AS cd_nm, sort_seq AS sort_sn, use_yn, sys_chg_usr_id AS mdfr_id, TO_CHAR(sys_chg_dttm, 'YYYY-MM-DD HH24:MI:SS') AS mdfcn_dt FROM cdm_own.cmmn_cd WHERE cd_grop_cd = 'SRVC_QSTN_CLSF_CD' AND lcal_cd = 'ko' AND use_yn = 'Y'
AND cmmn_cd_nm LIKE '%' || #{searchKeyword} || '%'
ORDER BY sort_seq, cmmn_cd

/* buttle.apptpl.sup.inquiry.mapper.InquiryTypeMapper.checkDuplicateCdNm */
SELECT COUNT(*)
FROM cdm_own.cmmn_cd
WHERE cd_grop_cd = 'SRVC_QSTN_CLSF_CD'
  AND lcal_cd = 'ko'
  AND cmmn_cd_nm = #{cdNm}

/* buttle.apptpl.sup.inquiry.mapper.InquiryTypeMapper.checkInquiryTypeInUse */
SELECT COUNT(*)
FROM cdm_own.cmpt_srvc_qstn
WHERE srvc_qstn_clsf_cd = #{cd}
